GenericityDetector.MASS_NOUNS = MASS_NOUNS;
GenericityDetector.STATIVE_VERBS = STATIVE_VERBS;
GenericityDetector.TENSE_GENERICITY_SIGNAL = TENSE_GENERICITY_SIGNAL;
